{-| @Backend.Runtime.Host.Raster — the software render device's raster kernels, as `Pudu.Runtime.Raster`, `Pudu.Runtime.Sampler` and `Pudu.Runtime.Shade` answer them. Every floating expression keeps the interpreter's order and grouping. -}
module Pudu.Backend.Runtime.Host.Raster (hostRasterParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostRasterParts :: [(Text, [Text], [Text])]
hostRasterParts =
  [ ("host_raster", ["host_lanes", "host_done", "kernel_fresh", "kernel_signed", "bytes_wrap", "memory_failure"],
      [ "#if defined(__clang__)"
      , "#pragma STDC FP_CONTRACT OFF"
      , "#endif"
      , "/* The interpreter's min and max: the first operand unless the order says otherwise. */"
      , "PUDU_OPTIONAL static inline double pudu_raster_min(double x, double y) { return x <= y ? x : y; }"
      , "PUDU_OPTIONAL static inline double pudu_raster_max(double x, double y) { return x <= y ? y : x; }"
      , "PUDU_OPTIONAL static inline int pudu_raster_finite(double x) { return !(isnan(x) || isinf(x)); }"
      , "/* A linear channel as an eight-bit code, rounded to nearest even. */"
      , "PUDU_OPTIONAL static inline unsigned char pudu_raster_channel(double value) {"
      , "  if (isnan(value) || value <= 0) return 0;"
      , "  if (value >= 1) return 255;"
      , "  return (unsigned char)rint(value * 255);"
      , "}"
      , "/* A written size as a place, or -1 when it is negative or does not fit. */"
      , "PUDU_OPTIONAL static inline int64_t pudu_raster_size(pudu_int written) {"
      , "  int64_t value = pudu_kernel_signed(written.bits);"
      , "  return written.negative || value < 0 ? -1 : value;"
      , "}"
      , "/* A floor or ceiling bound clamped into [low, high] before it becomes an index. */"
      , "PUDU_OPTIONAL static inline int64_t pudu_raster_bound(double value, int64_t low, int64_t high) {"
      , "  if (!(value > (double)low)) return low;"
      , "  if (value >= (double)high) return high;"
      , "  return (int64_t)value;"
      , "}"
      , "typedef struct { double x, y, z, r, g, b, q, u, v, nx, ny, nz, px, py, pz; } pudu_raster_vertex;"
      , "typedef struct { const unsigned char *texels; int64_t width, height; int srgb, bilinear; double table[256]; } pudu_raster_sampler;"
      , "typedef struct { double cx, cy, cz, lx, ly, lz, lr, lg, lb, ambient, power, strength, f0, hr, hg, hb, zr, zg, zb, sun, cutoff; } pudu_raster_light;"
      , "typedef struct { double r, g, b, a; } pudu_raster_texel;"
      , "typedef struct { unsigned char *color; unsigned char *depth; int64_t width, height; } pudu_raster_target;"
      , "PUDU_OPTIONAL static inline double pudu_raster_depth_at(const pudu_raster_target *target, int64_t at) {"
      , "  double value;"
      , "  memcpy(&value, target->depth + at * 8, 8);"
      , "  return value;"
      , "}"
      , "PUDU_OPTIONAL static inline double pudu_raster_edge(const pudu_raster_vertex *a, const pudu_raster_vertex *b, double x, double y) {"
      , "  return (b->x - a->x) * (y - a->y) - (b->y - a->y) * (x - a->x);"
      , "}"
      , "PUDU_OPTIONAL static inline int pudu_raster_top_left(const pudu_raster_vertex *a, const pudu_raster_vertex *b) {"
      , "  double dx = b->x - a->x, dy = b->y - a->y;"
      , "  return (dy == 0 && dx > 0) || dy < 0;"
      , "}"
      , "/* Texture storage: four bytes per texel, color space 0 linear or 1 sRGB, filter 0 nearest or 1 bilinear. */"
      , "PUDU_OPTIONAL static int pudu_raster_sampler_of(pudu_raster_sampler *sampler, pudu_box *texels, pudu_int width, pudu_int space, pudu_int filtering) {"
      , "  int64_t extent = pudu_raster_size(width), code = pudu_raster_size(space), mode = pudu_raster_size(filtering);"
      , "  size_t bytes = texels->fields[0].text.length, pixels = bytes / 4;"
      , "  if (extent < 0 || code < 0 || mode < 0) return 0;"
      , "  if (extent <= 0 || bytes % 4 != 0) return 0;"
      , "  if (pixels == 0 || pixels % (uint64_t)extent != 0) return 0;"
      , "  if (code > 1 || mode > 1) return 0;"
      , "  sampler->texels = texels->fields[0].text.bytes;"
      , "  sampler->width = extent;"
      , "  sampler->height = (int64_t)(pixels / (uint64_t)extent);"
      , "  sampler->srgb = code == 1;"
      , "  sampler->bilinear = mode == 1;"
      , "  for (int index = 0; index < 256; ++index) {"
      , "    double encoded = (double)index / 255;"
      , "    sampler->table[index] = encoded <= 0.04045 ? encoded / 12.92 : pow((encoded + 0.055) / 1.055, 2.4);"
      , "  }"
      , "  return 1;"
      , "}"
      , "PUDU_OPTIONAL static inline int64_t pudu_raster_clamp_index(int64_t size, int64_t index) { return index < 0 ? 0 : index >= size ? size - 1 : index; }"
      , "PUDU_OPTIONAL static pudu_raster_texel pudu_raster_texel_at(const pudu_raster_sampler *sampler, int64_t x, int64_t y) {"
      , "  const unsigned char *at = sampler->texels + (y * sampler->width + x) * 4;"
      , "  pudu_raster_texel texel;"
      , "  texel.r = sampler->srgb ? sampler->table[at[0]] : (double)at[0] / 255;"
      , "  texel.g = sampler->srgb ? sampler->table[at[1]] : (double)at[1] / 255;"
      , "  texel.b = sampler->srgb ? sampler->table[at[2]] : (double)at[2] / 255;"
      , "  texel.a = (double)at[3] / 255;"
      , "  return texel;"
      , "}"
      , "PUDU_OPTIONAL static inline double pudu_raster_lerp(double from, double to, double t) { return t == 0 ? from : t == 1 ? to : from + t * (to - from); }"
      , "PUDU_OPTIONAL static pudu_raster_texel pudu_raster_mix(pudu_raster_texel a, pudu_raster_texel b, double t) {"
      , "  pudu_raster_texel mixed;"
      , "  mixed.r = pudu_raster_lerp(a.r, b.r, t);"
      , "  mixed.g = pudu_raster_lerp(a.g, b.g, t);"
      , "  mixed.b = pudu_raster_lerp(a.b, b.b, t);"
      , "  mixed.a = pudu_raster_lerp(a.a, b.a, t);"
      , "  return mixed;"
      , "}"
      , "PUDU_OPTIONAL static pudu_raster_texel pudu_raster_premultiplied(pudu_raster_texel texel) {"
      , "  texel.r = texel.r * texel.a;"
      , "  texel.g = texel.g * texel.a;"
      , "  texel.b = texel.b * texel.a;"
      , "  return texel;"
      , "}"
      , "PUDU_OPTIONAL static inline double pudu_raster_unit(double x) { return x < 0 ? 0 : x > 1 ? 1 : x; }"
      , "/* Clamp-to-edge sampling at a normalized coordinate; non-finite coordinates answer transparent black. */"
      , "PUDU_OPTIONAL static pudu_raster_texel pudu_raster_sample(const pudu_raster_sampler *sampler, double u, double v) {"
      , "  pudu_raster_texel none = {0, 0, 0, 0}, a, b, c, d, mixed;"
      , "  double w = (double)sampler->width, h = (double)sampler->height, cu, cv, x, y, tx, ty, left, top;"
      , "  int64_t i, j;"
      , "  if (!(pudu_raster_finite(u) && pudu_raster_finite(v))) return none;"
      , "  cu = pudu_raster_unit(u);"
      , "  cv = pudu_raster_unit(v);"
      , "  if (!sampler->bilinear)"
      , "    return pudu_raster_texel_at(sampler, pudu_raster_clamp_index(sampler->width, (int64_t)floor(cu * w)), pudu_raster_clamp_index(sampler->height, (int64_t)floor(cv * h)));"
      , "  x = cu * w - 0.5;"
      , "  y = cv * h - 0.5;"
      , "  left = floor(x);"
      , "  top = floor(y);"
      , "  tx = x - left;"
      , "  ty = y - top;"
      , "  i = (int64_t)left;"
      , "  j = (int64_t)top;"
      , "  a = pudu_raster_premultiplied(pudu_raster_texel_at(sampler, pudu_raster_clamp_index(sampler->width, i), pudu_raster_clamp_index(sampler->height, j)));"
      , "  b = pudu_raster_premultiplied(pudu_raster_texel_at(sampler, pudu_raster_clamp_index(sampler->width, i + 1), pudu_raster_clamp_index(sampler->height, j)));"
      , "  c = pudu_raster_premultiplied(pudu_raster_texel_at(sampler, pudu_raster_clamp_index(sampler->width, i), pudu_raster_clamp_index(sampler->height, j + 1)));"
      , "  d = pudu_raster_premultiplied(pudu_raster_texel_at(sampler, pudu_raster_clamp_index(sampler->width, i + 1), pudu_raster_clamp_index(sampler->height, j + 1)));"
      , "  mixed = pudu_raster_mix(pudu_raster_mix(a, b, tx), pudu_raster_mix(c, d, tx), ty);"
      , "  if (mixed.a == 0) return none;"
      , "  mixed.r = mixed.r / mixed.a;"
      , "  mixed.g = mixed.g / mixed.a;"
      , "  mixed.b = mixed.b / mixed.a;"
      , "  return mixed;"
      , "}"
      , "/* Uniforms in a lane of twenty: camera, light direction and color, ambient, exponent, strength, f0, horizon, zenith, sun cosine. */"
      , "PUDU_OPTIONAL static int pudu_raster_light_of(pudu_raster_light *light, pudu_box *lane) {"
      , "  double v[20], size, brightest;"
      , "  if (pudu_lanes_held(lane) != 20) return 0;"
      , "  for (size_t i = 0; i < 20; ++i) { v[i] = pudu_lanes_at(lane, i); if (!pudu_raster_finite(v[i])) return 0; }"
      , "  size = sqrt(v[3] * v[3] + v[4] * v[4] + v[5] * v[5]);"
      , "  if (size <= 0) return 0;"
      , "  if (v[9] < 0 || v[9] > 1 || v[12] < 0 || v[12] > 1) return 0;"
      , "  if (v[10] <= 0 || v[11] < 0 || v[19] <= 0 || v[19] >= 1) return 0;"
      , "  light->cx = v[0]; light->cy = v[1]; light->cz = v[2];"
      , "  light->lx = v[3] / size; light->ly = v[4] / size; light->lz = v[5] / size;"
      , "  light->lr = v[6]; light->lg = v[7]; light->lb = v[8];"
      , "  light->ambient = v[9]; light->power = v[10]; light->strength = v[11]; light->f0 = v[12];"
      , "  light->hr = v[13]; light->hg = v[14]; light->hb = v[15];"
      , "  light->zr = v[16]; light->zg = v[17]; light->zb = v[18]; light->sun = v[19];"
      , "  brightest = pudu_raster_max(v[6], pudu_raster_max(v[7], v[8])) * v[11];"
      , "  light->cutoff = brightest <= 0 ? 2 : pow(1 / (512 * brightest), 1 / v[10]);"
      , "  return 1;"
      , "}"
      , "/* Lambert above an ambient floor, a Blinn-Phong highlight and a Schlick blend toward the sky. */"
      , "PUDU_OPTIONAL static void pudu_raster_shade(const pudu_raster_light *l, double nx0, double ny0, double nz0, double px, double py, double pz,"
      , "    double r, double g, double b, double *out) {"
      , "  double normal_length = sqrt(nx0 * nx0 + ny0 * ny0 + nz0 * nz0);"
      , "  double vx0 = l->cx - px, vy0 = l->cy - py, vz0 = l->cz - pz;"
      , "  double view_length = sqrt(vx0 * vx0 + vy0 * vy0 + vz0 * vz0);"
      , "  double vx, vy, vz, facing, side, nx, ny, nz, nv, diffuse, hx0, hy0, hz0, half_length, alignment, highlight;"
      , "  double fresnel, rest, rest2, rx, ry, rz, up, toward, disc;"
      , "  double base[3], light[3], horizon[3], zenith[3];"
      , "  if (normal_length <= 0 || view_length <= 0) { out[0] = r * l->ambient; out[1] = g * l->ambient; out[2] = b * l->ambient; return; }"
      , "  vx = vx0 / view_length;"
      , "  vy = vy0 / view_length;"
      , "  vz = vz0 / view_length;"
      , "  facing = (nx0 * vx + ny0 * vy + nz0 * vz) / normal_length;"
      , "  side = facing < 0 ? -(1 / normal_length) : 1 / normal_length;"
      , "  nx = nx0 * side;"
      , "  ny = ny0 * side;"
      , "  nz = nz0 * side;"
      , "  nv = pudu_raster_max(0, nx * vx + ny * vy + nz * vz);"
      , "  diffuse = l->ambient + (1 - l->ambient) * pudu_raster_max(0, nx * l->lx + ny * l->ly + nz * l->lz);"
      , "  hx0 = l->lx + vx;"
      , "  hy0 = l->ly + vy;"
      , "  hz0 = l->lz + vz;"
      , "  half_length = sqrt(hx0 * hx0 + hy0 * hy0 + hz0 * hz0);"
      , "  alignment = half_length <= 0 ? 0 : (nx * hx0 + ny * hy0 + nz * hz0) / half_length;"
      , "  highlight = alignment <= l->cutoff ? 0 : l->strength * pow(alignment, l->power);"
      , "  rest = 1 - nv;"
      , "  rest2 = rest * rest;"
      , "  fresnel = l->f0 + (1 - l->f0) * (rest2 * rest2 * rest);"
      , "  rx = 2 * nv * nx - vx;"
      , "  ry = 2 * nv * ny - vy;"
      , "  rz = 2 * nv * nz - vz;"
      , "  up = sqrt(pudu_raster_max(0, pudu_raster_min(1, ry)));"
      , "  toward = rx * l->lx + ry * l->ly + rz * l->lz;"
      , "  disc = toward <= l->sun ? 0 : pudu_raster_min(1, (toward - l->sun) / (1 - l->sun) * 4);"
      , "  base[0] = r; base[1] = g; base[2] = b;"
      , "  light[0] = l->lr; light[1] = l->lg; light[2] = l->lb;"
      , "  horizon[0] = l->hr; horizon[1] = l->hg; horizon[2] = l->hb;"
      , "  zenith[0] = l->zr; zenith[1] = l->zg; zenith[2] = l->zb;"
      , "  for (int k = 0; k < 3; ++k) {"
      , "    double sky = horizon[k] + (zenith[k] - horizon[k]) * up + light[k] * disc;"
      , "    out[k] = base[k] * diffuse * (1 - fresnel) + sky * fresnel + light[k] * highlight;"
      , "  }"
      , "}"
      , "PUDU_OPTIONAL static inline double pudu_raster_attribute(double l0, double l1, double l2, double f0, double f1, double f2, int perspective, double reciprocal) {"
      , "  double value = l0 * f0 + l1 * f1 + l2 * f2;"
      , "  return perspective ? value / reciprocal : value;"
      , "}"
      , "/* Fill a triangle of positive area at pixel centers; an edge pixel belongs to the triangle only on a top or left edge. */"
      , "PUDU_OPTIONAL static void pudu_raster_fill(pudu_raster_target *target, int perspective, const pudu_raster_sampler *texture, const pudu_raster_light *light,"
      , "    const pudu_raster_vertex *v0, const pudu_raster_vertex *v1, const pudu_raster_vertex *v2) {"
      , "  double area = pudu_raster_edge(v0, v1, v2->x, v2->y), inverse = 1 / area;"
      , "  int64_t low_x = pudu_raster_bound(floor(pudu_raster_min(pudu_raster_min(v0->x, v1->x), v2->x)), 0, INT64_MAX / 2);"
      , "  int64_t high_x = pudu_raster_bound(ceil(pudu_raster_max(pudu_raster_max(v0->x, v1->x), v2->x)), -1, target->width - 1);"
      , "  int64_t low_y = pudu_raster_bound(floor(pudu_raster_min(pudu_raster_min(v0->y, v1->y), v2->y)), 0, INT64_MAX / 2);"
      , "  int64_t high_y = pudu_raster_bound(ceil(pudu_raster_max(pudu_raster_max(v0->y, v1->y), v2->y)), -1, target->height - 1);"
      , "  int bias0 = pudu_raster_top_left(v1, v2), bias1 = pudu_raster_top_left(v2, v0), bias2 = pudu_raster_top_left(v0, v1);"
      , "  for (int64_t y = low_y; y <= high_y; ++y)"
      , "    for (int64_t x = low_x; x <= high_x; ++x) {"
      , "      double sx = (double)x + 0.5, sy = (double)y + 0.5;"
      , "      double w0 = pudu_raster_edge(v1, v2, sx, sy), w1 = pudu_raster_edge(v2, v0, sx, sy), w2 = pudu_raster_edge(v0, v1, sx, sy);"
      , "      double l0, l1, l2, z, reciprocal, held;"
      , "      int64_t at;"
      , "      pudu_raster_texel texel = {1, 1, 1, 1};"
      , "      if (!((w0 > 0 || (w0 == 0 && bias0)) && (w1 > 0 || (w1 == 0 && bias1)) && (w2 > 0 || (w2 == 0 && bias2)))) continue;"
      , "      l0 = w0 * inverse;"
      , "      l1 = w1 * inverse;"
      , "      l2 = w2 * inverse;"
      , "      z = l0 * v0->z + l1 * v1->z + l2 * v2->z;"
      , "      reciprocal = perspective ? l0 * v0->q + l1 * v1->q + l2 * v2->q : 1;"
      , "      at = y * target->width + x;"
      , "      held = pudu_raster_depth_at(target, at);"
      , "      if (!(z < held && reciprocal > 0 && !isinf(reciprocal))) continue;"
      , "      if (texture != NULL)"
      , "        texel = pudu_raster_sample(texture,"
      , "          pudu_raster_attribute(l0, l1, l2, v0->u, v1->u, v2->u, perspective, reciprocal),"
      , "          pudu_raster_attribute(l0, l1, l2, v0->v, v1->v, v2->v, perspective, reciprocal));"
      , "      if (!(texel.a >= 0.5)) continue;"
      , "      memcpy(target->depth + at * 8, &z, 8);"
      , "      {"
      , "        double red = pudu_raster_attribute(l0, l1, l2, v0->r, v1->r, v2->r, perspective, reciprocal) * texel.r;"
      , "        double green = pudu_raster_attribute(l0, l1, l2, v0->g, v1->g, v2->g, perspective, reciprocal) * texel.g;"
      , "        double blue = pudu_raster_attribute(l0, l1, l2, v0->b, v1->b, v2->b, perspective, reciprocal) * texel.b;"
      , "        double lit[3];"
      , "        if (light != NULL) {"
      , "          pudu_raster_shade(light,"
      , "            pudu_raster_attribute(l0, l1, l2, v0->nx, v1->nx, v2->nx, perspective, reciprocal),"
      , "            pudu_raster_attribute(l0, l1, l2, v0->ny, v1->ny, v2->ny, perspective, reciprocal),"
      , "            pudu_raster_attribute(l0, l1, l2, v0->nz, v1->nz, v2->nz, perspective, reciprocal),"
      , "            pudu_raster_attribute(l0, l1, l2, v0->px, v1->px, v2->px, perspective, reciprocal),"
      , "            pudu_raster_attribute(l0, l1, l2, v0->py, v1->py, v2->py, perspective, reciprocal),"
      , "            pudu_raster_attribute(l0, l1, l2, v0->pz, v1->pz, v2->pz, perspective, reciprocal),"
      , "            red, green, blue, lit);"
      , "        } else { lit[0] = red; lit[1] = green; lit[2] = blue; }"
      , "        target->color[at * 4] = pudu_raster_channel(lit[0]);"
      , "        target->color[at * 4 + 1] = pudu_raster_channel(lit[1]);"
      , "        target->color[at * 4 + 2] = pudu_raster_channel(lit[2]);"
      , "        target->color[at * 4 + 3] = 255;"
      , "      }"
      , "    }"
      , "}"
      , "PUDU_OPTIONAL static inline int pudu_raster_usable(const pudu_raster_vertex *v) {"
      , "  return pudu_raster_finite(v->x) && pudu_raster_finite(v->y) && v->z >= 0 && v->z <= 1;"
      , "}"
      , "/* Rasterize every triangle of the vertex lanes into copies of the targets; NULL when an operand is outside the kernel. */"
      , "PUDU_OPTIONAL static pudu_box *pudu_raster_draw(pudu_box *color, pudu_box *depth, pudu_int width, pudu_int cull,"
      , "    pudu_box *const *lanes, pudu_box *weights, pudu_box *us, pudu_box *vs, const pudu_raster_sampler *texture,"
      , "    pudu_box *const *surface, const pudu_raster_light *light) {"
      , "  int64_t columns = pudu_raster_size(width), culling = pudu_raster_size(cull);"
      , "  size_t pixels = pudu_lanes_held(depth), vertices = pudu_lanes_held(lanes[0]);"
      , "  pudu_raster_target target;"
      , "  unsigned char *color_bytes, *depth_bytes;"
      , "  pudu_box *answer;"
      , "  if (culling < 0 || culling > 1 || columns <= 0) return pudu_lanes_none();"
      , "  if (pixels % (uint64_t)columns != 0) return pudu_lanes_none();"
      , "  if (pixels > SIZE_MAX / 4 || color->fields[0].text.length != pixels * 4) return pudu_lanes_none();"
      , "  for (size_t i = 1; i < 6; ++i) if (pudu_lanes_held(lanes[i]) != vertices) return pudu_lanes_none();"
      , "  if (us != NULL && (pudu_lanes_held(us) != vertices || pudu_lanes_held(vs) != vertices)) return pudu_lanes_none();"
      , "  if (surface != NULL) for (size_t i = 0; i < 6; ++i) if (pudu_lanes_held(surface[i]) != vertices) return pudu_lanes_none();"
      , "  if (vertices % 3 != 0) return pudu_lanes_none();"
      , "  if (weights != NULL) {"
      , "    if (pudu_lanes_held(weights) != vertices) return pudu_lanes_none();"
      , "    for (size_t i = 0; i < vertices; ++i) { double w = pudu_lanes_at(weights, i); if (!(w > 0 && !isinf(w))) return pudu_lanes_none(); }"
      , "  }"
      , "  answer = pudu_box_new(2);"
      , "  answer->fields[0].box = pudu_bytes_wrap(pudu_kernel_fresh(pixels * 4, &color_bytes));"
      , "  answer->fields[1].box = pudu_bytes_wrap(pudu_kernel_fresh(pixels * 8, &depth_bytes));"
      , "  if (pixels != 0) {"
      , "    memcpy(color_bytes, color->fields[0].text.bytes, pixels * 4);"
      , "    memcpy(depth_bytes, depth->fields[0].text.bytes, pixels * 8);"
      , "  }"
      , "  target.color = color_bytes;"
      , "  target.depth = depth_bytes;"
      , "  target.width = columns;"
      , "  target.height = (int64_t)(pixels / (uint64_t)columns);"
      , "  for (size_t t = 0; t < vertices; t += 3) {"
      , "    pudu_raster_vertex corner[3];"
      , "    double q[3] = {1, 1, 1}, area;"
      , "    if (weights != NULL) {"
